def comps(grid, colors=(1,)):
 seen=set(); out=[]
 R,C=len(grid),len(grid[0])
 for r in range(R):
  for c in range(C):
   if grid[r][c] not in colors or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); comp=[]
   for x,y in q:
    comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and grid[a][b] in colors and (a,b) not in seen:
      seen.add((a,b));q.append((a,b))
   out.append(comp)
 return out
