def component_summary(grid):
 h,w=len(grid),len(grid[0]); seen=set(); result=[]
 for r in range(h):
  for c in range(w):
   if grid[r][c]==0 or (r,c) in seen:continue
   q=[(r,c)];seen.add((r,c)); cells=[]; colors=set()
   for x,y in q:
    cells.append((x,y))
    if grid[x][y]>1:colors.add(grid[x][y])
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and grid[a][b]!=0 and (a,b) not in seen:
      seen.add((a,b));q.append((a,b))
   result.append((len(cells),(min(x for x,y in cells),max(x for x,y in cells),min(y for x,y in cells),max(y for x,y in cells)),colors))
 return result
